# Bounded ONE-DAY empirical scenario layer proof. No account or backtest.
# Consumes exact full-size matrices generated by the production scenario
# source and validates the SHA256 source/data/settings signature before use.
using Dates, Serialization, LinearAlgebra, Random, Printf
BLAS.set_num_threads(parse(Int,get(ENV,"PROBE_BLAS_THREADS","4")))
include(joinpath(@__DIR__,"../src/gate0/KTraderGate0.jl"))
using .KTraderGate0
Base.include(KTraderGate0,joinpath(@__DIR__,"../src/gate0/market_io.jl"))
const G=KTraderGate0

data_dir=get(ENV,"GATE0_DATA_DIR","data")
mf=G.load_market_facts(data_dir)
el=G.Eligibility(mf)
date=Date(get(ENV,"PROBE_DATE","2024-10-01"))
top=parse(Int,get(ENV,"PROBE_CAPTURE_TOP","8192"))
8192<=top<=65536 && ispow2(top) || error("unsupported bounded replay layer")
low=top÷2
signature=G._backtest_signature(mf,el,(:qmc8192_real_one_day,
                                        date,1e-6,2048,5.0,
                                        G._DRIVER_DEFAULT_SEED,top))
path=abspath(get(ENV,"PROBE_CAPTURE_PATH",
             "/tmp/ktrader-two-year-20261011/one-day-qmc-$(top).jls"))
saved=deserialize(path)
(saved.version==2 && saved.date==date && saved.signature==signature &&
 saved.count>=390 && saved.Mlow==low && saved.Mhigh==top &&
 size(saved.X4096,1)==low && size(saved.X8192,1)==top &&
 size(saved.audit8192)==size(saved.X8192) &&
 isequal(saved.X4096,saved.X8192[1:low,:])) ||
    error("captured scenarios fail provenance or nesting checks")
N=size(saved.X8192,2)
N>=64 || error("not a real full-risk sample")
@printf("REAL_QMC_REPLAY date=%s risk=%d dnodes=%d low=%d high=%d timing_only=%s\n",
        date,N,length(saved.d_nodes),low,top,saved.timing_only)
flush(stdout)

results=Dict{Int,Any}()
for (M,X) in ((low,saved.X4096),(top,saved.X8192))
    t0=time_ns()
    result=G._cash_kelly_solve(X,zeros(M),ones(M),1.0,1e-6;backend=:ipm)
    if result.w_val===nothing
        println("NOT_CERTIFIED level=$M reason=$(result.reason)")
        exit(42)
    end
    w=result.w_val
    c=G.cash_kelly_certificate(X,collect(w[1:end-1]),w[end];base=zeros(M))
    success=result.status_ok && G.cash_kelly_certified(c;tol=1e-6)
    @printf("REAL_IPM_CERT M=%d ok=%s sec=%.5f gap=%.7g kkt=%.7g\n",
            M,success,(time_ns()-t0)/1e9,c.objective_gap,c.kkt_residual)
    @printf("IPM_SUPPORT M=%d cash=%.9g risky_sum=%.9g risky_gt_1e6=%d top_risky=%.9g\n",
            M,w[end],sum(w[1:end-1]),count(>(1e-6),w[1:end-1]),maximum(w[1:end-1]))
    flush(stdout)
    success || exit(43)
    results[M]=(;w,c)
end

w0=results[low].w
w1=results[top].w
objective(X,w)=sum(log, X*w[1:end-1] .+ w[end])/size(X,1)
A=sum(abs,w1.-w0)
Bopt=objective(saved.X8192,w1)-objective(saved.X8192,w0)
Baudit=abs(objective(saved.audit8192,w1)-objective(saved.audit8192,w0))
pass=A<=1e-4 && Bopt<=1e-6 && Baudit<=1e-6
@printf("REAL_QMC_REFINE low=%d high=%d A=%.9g Bopt=%.9g Baudit=%.9g pass=%s\n",
        low,top,A,Bopt,Baudit,pass)
flush(stdout)
exit(pass ? 0 : 45)
